// ============================================================
// Fetch GitHub data: commits, closed issues, merged PRs
// Edit the repoOwner and repoName below to configure
// ============================================================

const repoOwner = $getWorkflowStaticData('global').owner || 'claude-builders-bounty';
const repoName = $getWorkflowStaticData('global').repo || 'claude-builders-bounty';
const githubToken = $getWorkflowStaticData('global').githubToken || '';

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const since = weekAgo.toISOString();
const until = now.toISOString();

const headers = {
  'Accept': 'application/vnd.github.v3+json',
  'User-Agent': 'n8n-weekly-summary'
};
if (githubToken) {
  headers['Authorization'] = `token ${githubToken}`;
}

async function fetchJSON(url) {
  const response = await fetch(url, { headers });
  if (!response.ok) {
    throw new Error(`GitHub API error ${response.status}: ${await response.text()}`);
  }
  return response.json();
}

// Fetch all three in parallel
const baseUrl = `https://api.github.com/repos/${repoOwner}/${repoName}`;

const [commits, issues, pulls] = await Promise.all([
  fetchJSON(`${baseUrl}/commits?since=${since}&until=${until}&per_page=15`),
  fetchJSON(`${baseUrl}/issues?state=closed&since=${since}&per_page=15`),
  fetchJSON(`${baseUrl}/pulls?state=closed&sort=updated&direction=desc&per_page=15`)
]);

return [{
  json: {
    repoOwner,
    repoName,
    since,
    until,
    commits: (commits || []).map(c => ({
      sha: c.sha?.substring(0, 7) || '',
      message: c.commit?.message?.split('\n')[0] || '',
      author: c.commit?.author?.name || c.author?.login || '',
      date: c.commit?.author?.date || ''
    })),
    issues: (issues || [])
      .filter(i => !i.pull_request)
      .map(i => ({
        number: i.number,
        title: i.title,
        state: i.state,
        author: i.user?.login || '',
        created_at: i.created_at,
        closed_at: i.closed_at,
        labels: (i.labels || []).map(l => l.name)
      })),
    pulls: (pulls || [])
      .filter(p => p.merged_at)
      .map(p => ({
        number: p.number,
        title: p.title,
        author: p.user?.login || '',
        merged_at: p.merged_at,
        additions: p.additions,
        deletions: p.deletions
      }))
  }
}];

// Format all data into the Claude API message format
const items = [];

for (const item of $input.all()) {
  const d = item.json;
  const repo = `${d.repoOwner}/${d.repoName}`;

  // Build the prompt
  const commitSection = (d.commits?.length > 0)
    ? d.commits.map(c => `- \`${c.sha}\` ${c.message} (${c.author})`).join('\n')
    : 'No commits this week.';

  const issueSection = (d.issues?.length > 0)
    ? d.issues.map(i => `- #${i.number}: ${i.title} (by ${i.author}, closed ${new Date(i.closed_at).toDateString()})`).join('\n')
    : 'No issues closed this week.';

  const prSection = (d.pulls?.length > 0)
    ? d.pulls.map(p => `- #${p.number}: ${p.title} (by ${p.author}, +${p.additions}/-${p.deletions} lines)`).join('\n')
    : 'No PRs merged this week.';

  const period = `${new Date(d.since).toDateString()} — ${new Date(d.until).toDateString()}`;

  items.push({
    json: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 2048,
      messages: [
        {
          role: 'user',
          content: `Generate a weekly development summary for the GitHub repository **${repo}**.

## Period
${period}

## Commits (${d.commits?.length || 0})
${commitSection}

## Closed Issues (${d.issues?.length || 0})
${issueSection}

## Merged Pull Requests (${d.pulls?.length || 0})
${prSection}

Please provide:
1. A narrative summary (2-3 paragraphs) of the week's activity
2. Key highlights and achievements
3. Areas needing attention (if any)
4. Overall project health assessment

Write in a professional, friendly tone.`
        }
      ]
    }
  });
}

return items;

// Parse Claude API response
const items = [];
for (const item of $input.all()) {
  const response = item.json;
  const summaryText = response.content?.[0]?.text 
    || response.content?.toString() 
    || JSON.stringify(response);

  items.push({
    json: {
      summary: summaryText,
      generated_at: new Date().toISOString(),
      model: response.model || 'claude-sonnet-4-20250514',
      input_tokens: response.usage?.input_tokens || 0,
      output_tokens: response.usage?.output_tokens || 0
    }
  });
}
return items;
